#![forbid(unsafe_code)]
use localview_protocol::SemanticNode;
use serde::{Deserialize,Serialize};
#[derive(Debug,Clone,Serialize,Deserialize)]pub struct A11yFinding{pub code:String,pub reference:String,pub message:String,pub deterministic:bool,pub confidence:u8}
pub fn audit(root:&SemanticNode)->Vec<A11yFinding>{let mut out=Vec::new();walk(root,&mut out);out}
fn walk(n:&SemanticNode,out:&mut Vec<A11yFinding>){let role=n.role.as_deref().unwrap_or("");if n.interactive&&n.name.as_deref().unwrap_or("").trim().is_empty(){out.push(A11yFinding{code:"interactive_name_missing".into(),reference:n.reference.clone(),message:"Interactive control has no accessible name".into(),deterministic:true,confidence:100});}if role=="img"&&n.name.as_deref().unwrap_or("").trim().is_empty(){out.push(A11yFinding{code:"image_name_missing".into(),reference:n.reference.clone(),message:"Image lacks an accessible alternative".into(),deterministic:true,confidence:100});}if let Some(r)=&n.rect{if n.interactive&&(r.width<24.0||r.height<24.0){out.push(A11yFinding{code:"small_hit_target".into(),reference:n.reference.clone(),message:format!("Hit target is {:.0}×{:.0}px",r.width,r.height),deterministic:false,confidence:84});}}for c in &n.children{walk(c,out)}}
#[cfg(test)]mod tests{use super::*;use std::collections::BTreeMap;#[test]fn nameless_button_is_flagged(){let n=SemanticNode{reference:"@1".into(),role:Some("button".into()),name:None,tag:"button".into(),rect:None,interactive:true,attributes:BTreeMap::new(),source:None,children:vec![]};assert_eq!(audit(&n)[0].code,"interactive_name_missing");}}
